DROP TABLE IF EXISTS `answers`;
CREATE TABLE `answers` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `exam_id` int(11) DEFAULT NULL,
  `question_id` int(11) DEFAULT NULL,
  `student_id` int(11) DEFAULT NULL,
  `examiner_id` int(11) DEFAULT NULL,
  `score` decimal(5,2) DEFAULT NULL,
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_by` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `question_id` (`question_id`),
  KEY `student_id` (`student_id`),
  KEY `examiner_id` (`examiner_id`),
  KEY `idx_exam_student_question` (`exam_id`,`student_id`,`question_id`),
  KEY `fk_answers_updated_by` (`updated_by`),
  CONSTRAINT `answers_ibfk_1` FOREIGN KEY (`exam_id`) REFERENCES `exams` (`id`),
  CONSTRAINT `answers_ibfk_2` FOREIGN KEY (`question_id`) REFERENCES `questions` (`id`),
  CONSTRAINT `answers_ibfk_3` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`),
  CONSTRAINT `answers_ibfk_4` FOREIGN KEY (`examiner_id`) REFERENCES `examiners` (`id`),
  CONSTRAINT `fk_answers_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `examiners` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=33460 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `center_links`;
CREATE TABLE `center_links` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `group_id` int(11) NOT NULL,
  `main_url` varchar(255) DEFAULT NULL,
  `prefix` varchar(12) NOT NULL,
  `pkg_key` char(64) NOT NULL,
  `center_name` varchar(190) DEFAULT NULL,
  `center_code` varchar(40) DEFAULT NULL,
  `package_version` int(11) DEFAULT NULL,
  `activated_at` datetime DEFAULT NULL,
  `last_sync_at` datetime DEFAULT NULL,
  `last_sync_status` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_link_prefix` (`prefix`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

DROP TABLE IF EXISTS `center_students`;
CREATE TABLE `center_students` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `token_id` int(11) NOT NULL,
  `student_id` int(11) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_cs` (`token_id`,`student_id`),
  KEY `idx_cs_student` (`student_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

DROP TABLE IF EXISTS `center_tokens`;
CREATE TABLE `center_tokens` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `group_id` int(11) NOT NULL,
  `center_id` int(11) NOT NULL,
  `prefix` varchar(12) NOT NULL,
  `pkg_key` char(64) NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'issued',
  `issued_at` datetime NOT NULL DEFAULT current_timestamp(),
  `issued_by` varchar(100) DEFAULT NULL,
  `activated_at` datetime DEFAULT NULL,
  `activated_ip` varchar(64) DEFAULT NULL,
  `last_download_at` datetime DEFAULT NULL,
  `last_sync_at` datetime DEFAULT NULL,
  `sync_count` int(11) NOT NULL DEFAULT 0,
  `revoked_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_token_prefix` (`prefix`),
  KEY `idx_ct_group` (`group_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

DROP TABLE IF EXISTS `device_approval_log`;
CREATE TABLE `device_approval_log` (
