) ENGINE=InnoDB AUTO_INCREMENT=43 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `examiners`;
CREATE TABLE `examiners` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) DEFAULT NULL,
  `username` varchar(100) DEFAULT NULL,
  `password` varchar(255) DEFAULT NULL,
  `role` varchar(20) NOT NULL DEFAULT 'examiner',
  `deleted_at` timestamp NULL DEFAULT NULL,
  `source` varchar(20) NOT NULL DEFAULT 'manual' COMMENT 'Origin: manual, exeat2, upload',
  `external_id` bigint(20) unsigned DEFAULT NULL COMMENT 'FK to exeat2.staff.id if source=exeat2',
  `email` varchar(255) DEFAULT NULL,
  `firstname` varchar(100) DEFAULT NULL,
  `lastname` varchar(100) DEFAULT NULL,
  `group_id` int(11) DEFAULT NULL,
  `session_token` varchar(128) DEFAULT NULL,
  `last_seen_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `username` (`username`),
  KEY `idx_source` (`source`),
  KEY `idx_external_id` (`external_id`),
  KEY `idx_examiners_group` (`group_id`)
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `exams`;
CREATE TABLE `exams` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `session_id` int(11) DEFAULT NULL,
  `name` varchar(255) DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT 0,
  `created_at` datetime DEFAULT current_timestamp(),
  `type` enum('practical','objective','viva','research') DEFAULT 'practical',
  `student_can_view_score` tinyint(1) DEFAULT 0,
  `description` text DEFAULT NULL,
  `total_mark` decimal(6,2) DEFAULT NULL,
  `open_at` datetime DEFAULT NULL,
  `close_at` datetime DEFAULT NULL,
  `duration_minutes` int(11) DEFAULT 0,
  `max_attempts` int(11) DEFAULT 1,
  `score_policy` enum('highest','first','last') DEFAULT 'highest',
  `shuffle_objective` tinyint(1) DEFAULT 0,
  `questions_to_show` int(11) DEFAULT 0,
  `grading_method` varchar(20) DEFAULT 'highest',
  `is_strict` tinyint(1) DEFAULT 1,
  `shuffle_options` tinyint(1) DEFAULT 1,
  `partial_scoring` tinyint(1) NOT NULL DEFAULT 1,
  `math_notation` tinyint(1) NOT NULL DEFAULT 0,
  `proctor_fullscreen` tinyint(1) DEFAULT 0,
  `proctor_tab_lock` tinyint(1) DEFAULT 0,
  `proctor_kb_lock` tinyint(1) DEFAULT 0,
  `proctor_auto_submit` tinyint(1) DEFAULT 0,
  `proctor_browser_check` tinyint(1) DEFAULT 0,
  `proctor_webcam` tinyint(1) DEFAULT 0,
  `proctor_live_video` tinyint(1) DEFAULT 0,
  `start_time` datetime DEFAULT NULL,
  `end_time` datetime DEFAULT NULL,
  `late_start_minutes` int(11) DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `group_id` int(11) DEFAULT NULL,
  `remote_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_exams_group` (`group_id`)
) ENGINE=InnoDB AUTO_INCREMENT=139 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `objective_answers`;
CREATE TABLE `objective_answers` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `exam_id` int(11) NOT NULL,
  `student_id` int(11) NOT NULL,
  `question_id` int(11) NOT NULL,
  `selected_option` varchar(255) NOT NULL DEFAULT '',
  `submitted_at` datetime NOT NULL,
  `attempt_no` int(11) DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_unique_exam_attempt_question` (`exam_id`,`student_id`,`attempt_no`,`question_id`),
  KEY `exam_id` (`exam_id`),
  KEY `student_id` (`student_id`),
  KEY `question_id` (`question_id`),
  CONSTRAINT `objective_answers_ibfk_1` FOREIGN KEY (`exam_id`) REFERENCES `exams` (`id`) ON DELETE CASCADE,
  CONSTRAINT `objective_answers_ibfk_2` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE,
  CONSTRAINT `objective_answers_ibfk_3` FOREIGN KEY (`question_id`) REFERENCES `objective_questions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=28342 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `objective_attempts`;
CREATE TABLE `objective_attempts` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `exam_id` int(11) NOT NULL,
  `student_id` int(11) NOT NULL,
  `login_id` int(11) DEFAULT NULL,
  `attempt_no` int(11) NOT NULL,
  `started_at` datetime DEFAULT NULL,
  `finished_at` datetime DEFAULT NULL,
  `time_taken` int(11) DEFAULT NULL,
  `time_used` int(11) NOT NULL DEFAULT 0,
  `last_tick_at` datetime DEFAULT NULL,
  `question_order` text DEFAULT NULL,
  `score` decimal(10,2) DEFAULT NULL,
  `violation_count` int(11) DEFAULT 0,
  `is_locked` tinyint(1) DEFAULT 0,
  `last_active` datetime DEFAULT current_timestamp(),
  `proctor_status` enum('active','blur','disconnected','submitted') DEFAULT 'active',
  `webcam_snapshot` longtext DEFAULT NULL,
  `snapshot_path` varchar(255) DEFAULT NULL,
  `is_live_requested` tinyint(1) DEFAULT 0,
  `last_warning_at` datetime DEFAULT NULL,
  `warning_message` text DEFAULT NULL,
  `remote_command` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `exam_id` (`exam_id`,`student_id`,`attempt_no`),
  KEY `idx_oa_exam_open` (`exam_id`,`finished_at`),
  KEY `idx_oa_student_exam` (`student_id`,`exam_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1776 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `objective_questions`;
CREATE TABLE `objective_questions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `exam_id` int(11) NOT NULL,
  `question_type` varchar(20) NOT NULL DEFAULT 'mcq_single',
  `question_text` text NOT NULL,
  `question_image` varchar(255) DEFAULT NULL,
  `question_data` text DEFAULT NULL,
  `option_a` varchar(1000) NOT NULL DEFAULT '',
  `option_a_image` varchar(255) DEFAULT NULL,
  `option_b` varchar(1000) NOT NULL DEFAULT '',
  `option_b_image` varchar(255) DEFAULT NULL,
  `option_c` varchar(1000) NOT NULL DEFAULT '',
  `option_c_image` varchar(255) DEFAULT NULL,
  `option_d` varchar(1000) NOT NULL DEFAULT '',
  `option_d_image` varchar(255) DEFAULT NULL,
  `correct_option` varchar(64) NOT NULL DEFAULT '',
  `mark` float DEFAULT 1,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `exam_id` (`exam_id`),
  KEY `idx_oq_exam_live` (`exam_id`,`deleted_at`),
  CONSTRAINT `objective_questions_ibfk_1` FOREIGN KEY (`exam_id`) REFERENCES `exams` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1037 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `questions`;
CREATE TABLE `questions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `exam_id` int(11) DEFAULT NULL,
  `text` varchar(500) DEFAULT NULL,
  `score_values` varchar(50) DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `exam_id` (`exam_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1483 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `students`;
CREATE TABLE `students` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) DEFAULT NULL,
  `firstname` varchar(100) DEFAULT NULL,
  `middlename` varchar(100) DEFAULT NULL,
  `lastname` varchar(100) DEFAULT NULL,
  `email` varchar(150) DEFAULT NULL,
  `matric_no` varchar(50) DEFAULT NULL,
  `username` varchar(100) DEFAULT NULL,
  `password` varchar(255) DEFAULT '12345',
  `current_session_id` varchar(255) DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `source` varchar(20) NOT NULL DEFAULT 'upload' COMMENT 'Origin: upload, exeat2, manual',
  `external_id` bigint(20) unsigned DEFAULT NULL COMMENT 'FK to exeat2.students.id if source=exeat2',
  PRIMARY KEY (`id`),
  UNIQUE KEY `matric_no` (`matric_no`),
  UNIQUE KEY `username` (`username`),
  KEY `idx_source` (`source`),
  KEY `idx_external_id` (`external_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3570 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `sync_log`;
CREATE TABLE `sync_log` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `token_id` int(11) DEFAULT NULL,
  `link_id` int(11) DEFAULT NULL,
  `action` varchar(30) NOT NULL,
