(191, 62, ''mcq_single'', ''What is the primary purpose of tepid sponging in a client with a high fever?'', NULL, NULL, ''To cause shivering and raise body temperature.'', NULL, ''To reduce body temperature through evaporation and conduction.'', NULL, ''To provide comfort by using freezing water.'', NULL, ''To cleanse the skin thoroughly with soap.'', NULL, ''B'', 1, NULL),
(192, 62, ''mcq_single'', ''The following are true of  hypothermia EXCEPT….'', NULL, NULL, ''Caused by excessive heat loss'', NULL, ''Caused by excessive heat gain'', NULL, ''The in adequate heat production to counteract the at loss'', NULL, ''May be accidental or induced'', NULL, ''B'', 1, NULL),
