(361, 77, ''mcq_single'', ''What should the nurse look out for while checking a patient\'s pulse?'', NULL, NULL, ''Patient\'s facial expression'', NULL, ''Volume and rhythm'', NULL, ''Tachycardia'', NULL, ''Skin texture'', NULL, ''A'', 1, NULL),
(362, 77, ''mcq_single'', ''During BP check, the nurse should be very particular about:'', NULL, NULL, ''The chest wall'', NULL, ''Patient not talking'', NULL, ''The diastolic phase of the reading'', NULL, ''None of the above'', NULL, ''C'', 1, NULL),
(363, 77, ''mcq_single'', ''A child with body temperature iof 38.8°C. What should the nurse do first?'', NULL, NULL, ''Reassure mother and tepid sponge the child'', NULL, ''Administer paracetamol syrup'', NULL, ''Cover child with blanket'', NULL, ''All of the above'', NULL, ''A'', 1, NULL),
(364, 77, ''mcq_single'', ''4 An elderly male patient with BP of 85/55 mmHg. What should the nurse do?'', NULL, NULL, ''Bring patient out of bed'', NULL, ''Reassure patient'', NULL, ''Raise foot of bed and increase infusion flow'', NULL, ''Reduce infusion and elevate foot of bed'', NULL, ''C'', 1, NULL),
(365, 77, ''mcq_single'', ''If a post-op patient\'s pulse suddenly becomes rapid, the nurse should observe the op-site for:'', NULL, NULL, ''Pain'', NULL, ''Bleeding'', NULL, ''Swelling'', NULL, ''Healing'', NULL, ''B'', 1, NULL),
