(378, 97, ''mcq_single'', ''The most common cause of primary postpartum haemorrhage is'', NULL, NULL, ''Retained placenta'', NULL, ''Cervical laceration'', NULL, ''Uterine atony'', NULL, ''Coagulation disorder'', NULL, ''C'', 1, NULL),
(379, 97, ''mcq_single'', ''Which action would have the GREATEST impact on reducing measles cases in a community?'', NULL, NULL, ''Increasing hospital admissions'', NULL, ''Expanding routine immunization coverage'', NULL, ''Purchasing more antibiotics'', NULL, ''Building additional clinics'', NULL, ''B'', 1, NULL),
