(504, 120, ''mcq_single'', ''What is the recommended flow rate for ear irrigation?'', NULL, NULL, ''10-20 mL/min'', NULL, ''20-30 mL/min'', NULL, ''30-50 mL/min'', NULL, ''50-100 mL/min'', NULL, ''C'', 1, NULL),
(505, 120, ''mcq_single'', ''After ear irrigation, what should the nurse instruct the patient to do?'', NULL, NULL, ''Insert earplugs'', NULL, ''Avoid getting the ear wet'', NULL, ''Dry the ear canal with a towel'', NULL, ''Shake their head to remove excess water'', NULL, ''C'', 1, NULL),
