(508, 120, ''mcq_single'', ''What should the nurse use to irrigate the ear canal?'', NULL, NULL, ''Syringe with a large tip'', NULL, ''Syringe with a small tip'', NULL, ''Ear dropper'', NULL, ''Irrigation syringe with a flexible tip'', NULL, ''D'', 1, NULL),
(509, 120, ''mcq_single'', ''How far should the tip of the irrigation syringe be inserted into the ear canal?'', NULL, NULL, ''1-2 cm'', NULL, ''2-3 cm'', NULL, ''3-5 cm'', NULL, ''5-7 cm'', NULL, ''A'', 1, NULL),
(510, 120, ''mcq_single'', ''After ear irrigation, what should the nurse instruct the patient to report?'', NULL, NULL, ''Any discharge or bleeding from the ear'', NULL, ''Any pain or discomfort in the ear'', NULL, ''Any changes in hearing or balance'', NULL, ''All of the above'', NULL, ''D'', 1, NULL),
(511, 121, ''mcq_single'', ''What is the definition of IM injection?'', NULL, NULL, ''Introduction of hypodermic needle into muscle to administer a medication.'', NULL, ''Introduction of hypodermic needle into skin to administer a medication.'', NULL, ''Introduction of hypodermic needle into bone to administer a medication.'', NULL, ''None of the above.'', NULL, ''A'', 1, NULL),
(512, 121, ''mcq_single'', ''Which value does not determine for administration of IM injection?'', NULL, NULL, ''Age'', NULL, ''Blood pressure'', NULL, ''Body mass'', NULL, ''Amount of medication'', NULL, ''B'', 1, NULL),
(513, 121, ''mcq_single'', ''Which of the following statement is true on using alcohol swab, to clean the injection site?'', NULL, NULL, ''Clean the site in a circular motion for 15 seconds and allow to dry for 15 seconds prior to administration.'', NULL, ''Clean the site in a circular motion for 30 seconds and allow to dry for 30 seconds prior to administration.'', NULL, ''Clean the site in a circular motion for 5 seconds and allow to dry for 5 seconds prior to administration.'', NULL, ''Clean the site in a circular motion for 20 seconds and allow to dry for 20 seconds prior to administration.'', NULL, ''C'', 1, NULL),
(514, 121, ''mcq_single'', ''Skin should always be cleansed prior to which of the following condition before giving IM injection?'', NULL, NULL, ''If the patient is receiving heparin.'', NULL, ''If the patient is a diabetic.'', NULL, ''If the patient is immunocompromised.'', NULL, ''If the patient has peripheral shutdown.'', NULL, ''C'', 1, NULL),
(515, 121, ''mcq_single'', ''Which of the following is the typical Needle size that’s used for an IM injection?'', NULL, NULL, ''22 to 25 gauge'', NULL, ''25 to 27 gauge'', NULL, ''18 to 20 gauge'', NULL, ''28 to 30 gauges.'', NULL, ''C'', 1, NULL),
(516, 121, ''mcq_single'', ''Which of the following is advocated as the safest site for an IM injection?'', NULL, NULL, ''Vastus lateralis'', NULL, ''Ventrogluteal site'', NULL, ''Deltoid muscles'', NULL, ''Dorsogluteal muscles'', NULL, ''C'', 1, NULL),
(517, 121, ''mcq_single'', ''What is the maximum volume of medication that can be received into the ventrogluteal site during an intramuscular injection?'', NULL, NULL, ''8.5 ml'', NULL, ''6.5 ml'', NULL, ''4.5 ml'', NULL, ''2.5 ml'', NULL, ''D'', 1, NULL),
(518, 121, ''mcq_single'', ''Why should an intramuscular injection be given at a 90 – degree angle?'', NULL, NULL, ''To ensure medication reaches the muscle'', NULL, ''Because the IM route allows a relatively quick uptake of the drug'', NULL, ''To avoid the needle for skin cleansing'', NULL, ''It increases the chance of giving the drug intravenously'', NULL, ''A'', 1, NULL),
(519, 121, ''mcq_single'', ''Why should IM injections be given at a rate of about 1 ml every ten seconds?'', NULL, NULL, ''To allow muscle fibers to expand, allowing the drug to be absorbed'', NULL, ''To check for blood aspiration'', NULL, ''To prevent medication being given intravenously'', NULL, ''To prevent hematoma formation'', NULL, ''A'', 1, NULL),
(520, 121, ''mcq_single'', ''The deltoid intramuscular site is below which body region?'', NULL, NULL, ''Buttock region'', NULL, ''Hip region'', NULL, ''Thigh region'', NULL, ''Arm region'', NULL, ''B'', 1, NULL),
(521, 121, ''mcq_single'', ''What is the primary purpose of an IM injection?'', NULL, NULL, ''To administer medication into a vein'', NULL, ''To administer medication into a muscle'', NULL, ''To administer medication into the spine'', NULL, ''To administer medication into the skin'', NULL, ''B'', 1, NULL),
(522, 121, ''mcq_single'', ''Which of the following is a suitable site for an IM injection?'', NULL, NULL, ''Deltoid muscle'', NULL, ''Gluteus maximus muscle'', NULL, ''Rectus femoris muscle'', NULL, ''All of the above'', NULL, ''D'', 1, NULL),
(523, 121, ''mcq_single'', ''What is the recommended needle length for an IM injection in an adult?'', NULL, NULL, ''1-2 inches (2.5-5 cm)'', NULL, ''2-3 inches (5-7.5 cm)'', NULL, ''3-4 inches (7.5-10 cm)'', NULL, ''4-5 inches (10-12.5 cm)'', NULL, ''B'', 1, NULL),
(524, 121, ''mcq_single'', ''Which of the following is a contraindication for an IM injection?'', NULL, NULL, ''Allergic reaction to the medication'', NULL, ''Bleeding disorder'', NULL, ''Muscle atrophy'', NULL, ''All of the above'', NULL, ''D'', 1, NULL),
(525, 121, ''mcq_single'', ''What is the recommended injection technique for an IM injection?'', NULL, NULL, ''Z-track technique'', NULL, ''Airlock technique'', NULL, ''Subcutaneous technique'', NULL, ''Intradermal technique'', NULL, ''A'', 1, NULL),
(526, 121, ''mcq_single'', ''What is the purpose of aspirating before injecting medication IM?'', NULL, NULL, ''To ensure the needle is in the muscle'', NULL, ''To prevent injection into a blood vessel'', NULL, ''To reduce discomfort during injection'', NULL, ''To increase medication absorption'', NULL, ''B'', 1, NULL),
(527, 121, ''mcq_single'', ''Which of the following medications is typically administered IM?'', NULL, NULL, ''Insulin'', NULL, ''Heparin'', NULL, ''Vaccines'', NULL, ''Chemotherapy'', NULL, ''C'', 1, NULL),
(528, 121, ''mcq_single'', ''What is the recommended angle for inserting the needle for an IM injection?'', NULL, NULL, ''15-20 degrees'', NULL, ''30-45 degrees'', NULL, ''60-90 degrees'', NULL, ''90-120 degrees'', NULL, ''C'', 1, NULL),
(529, 121, ''mcq_single'', ''How long should the needle remain in the muscle after injection?'', NULL, NULL, ''1-2 seconds'', NULL, ''2-5 seconds'', NULL, ''5-10 seconds'', NULL, ''10-30 seconds'', NULL, ''C'', 1, NULL),
(530, 121, ''mcq_single'', ''What should the nurse do after administering an IM injection?'', NULL, NULL, ''Massage the injection site'', NULL, ''Apply a cold compress'', NULL, ''Apply a topical antibiotic ointment'', NULL, ''Document the injection and monitor for adverse reactions'', NULL, ''D'', 1, NULL),
(531, 130, ''mcq_single'', ''Which of the following describes the most clinically effective method to ensure all transient microorganisms are mechanically removed from the hands during routine handwashing?'', NULL, NULL, ''Rinsing the hands under lukewarm water for 60 seconds without scrubbing'', NULL, ''Rubbing the hands together with a dry paper towel before applying water'', NULL, ''Scrubbing all surfaces of the hands vigorously with soap and running water for at least 20 seconds'', NULL, ''Immersing the hands in a stationary basin filled with antiseptic solution for 5 seconds'', NULL, ''C'', 1, NULL),
(532, 130, ''mcq_single'', ''When using an alcohol-based hand rub for routine hand hygiene, which action ensures the technique is fully effective?'', NULL, NULL, ''Wiping off the excess hand rub with a tissue immediately after application'', NULL, ''Rubbing the hands together covering all surfaces until they are completely dry'', NULL, ''Washing the hands with soap and water immediately before applying the rub'', NULL, ''Applying the gel exclusively to the fingertips and palms without touching the thumbs'', NULL, ''B'', 1, NULL),
(533, 130, ''mcq_single'', ''According to global hand hygiene guidelines, which of the following is considered a critical requirement prior to performing medical handwashing?'', NULL, NULL, ''Applying a thick layer of oil-based moisturizing lotion to the skin'', NULL, ''Keeping fingernails long to protect the underlying nail beds'', NULL, ''Wearing multiple rings and bracelets to keep track of personal items'', NULL, ''Removing all wrist jewelry, rings, and rolling up long sleeves'', NULL, ''D'', 1, NULL),
(534, 130, ''mcq_single'', ''When following the standard 6-step handwashing technique, which specific movement is required to properly clean the interdigital spaces (between the fingers)?'', NULL, NULL, ''Rubbing the tips of the fingers against the palm in a circular motion'', NULL, ''Rotational rubbing of the thumbs clasped in the opposing palm'', NULL, ''Rubbing palm to palm with the fingers interlaced'', NULL, ''Interlocking the backs of the fingers against the opposing palm'', NULL, ''C'', 1, NULL),
(535, 130, ''mcq_single'', ''What is the primary public health rationale for insisting on the use of running water rather than a shared water basin for hand hygiene?'', NULL, NULL, ''Running water maintains a higher temperature than basin water'', NULL, ''Shared basins trap and re-contaminate hands with dislodged pathogens'', NULL, ''Running water uses significantly less soap to create a proper lather'', NULL, ''Basin water completely neutralizes the chemical properties of plain soap'', NULL, ''B'', 1, NULL),
(536, 130, ''mcq_single'', ''During the 6-step handwashing sequence, how should a healthcare worker ensure that the fingernails and subungual areas are properly cleansed?'', NULL, NULL, ''By scratching the rough surface of a clean towel or sponge'', NULL, ''By rubbing the fingertips rotationally backward and forward in the opposing palm'', NULL, ''By using a metal nail file between washing individual fingers'', NULL, ''By relying entirely on the force of the running water stream'', NULL, ''B'', 1, NULL),
(537, 130, ''mcq_single'', ''Under the WHO \"My 5 Moments for Hand Hygiene,\" which clinical scenario strictly requires hand hygiene before touching a patient?'', NULL, NULL, ''Immediately after removing sterile latex gloves post-procedure'', NULL, ''Upon entering the room before performing a physical assessment or checking a pulse'', NULL, ''After adjusting a patient\'s dirty bed linens or drainage bag'', NULL, ''When leaving the patient\'s immediate environment to document charts'', NULL, ''B'', 1, NULL),
(538, 130, ''mcq_single'', ''Which of the following actions is a vital component of the \"Right Documentation\" or correct technique sequence when drying hands after handwashing?'', NULL, NULL, ''Rubbing the hands vigorously against personal clothing or uniform fabric'', NULL, ''Using a shared, damp cloth towel kept near the community sink'', NULL, ''Allowing the hands to air-dry completely or using a clean, single-use disposable towel'', NULL, ''Blowing hot breath onto the hands to speed up evaporation'', NULL, ''C'', 1, NULL),
(539, 130, ''mcq_single'', ''Why is the routine use of alcohol-based hand rubs strictly contraindicated when caring for a pediatric patient with confirmed Clostridioides difficile or acute watery diarrhea suspected to be spore-forming?'', NULL, NULL, ''Alcohol rubs can cause severe allergic contact dermatitis in young children'', NULL, ''Alcohol rubs do not destroy bacterial spores, requiring physical removal with soap and water'', NULL, ''The gel instantly inactivates the low-osmolarity fluids being administered'', NULL, ''Rubs interact negatively with oral zinc supplementation guidelines'', NULL, ''B'', 1, NULL),
(540, 130, ''mcq_single'', ''During a home visit, a public health nurse notes that a household has no access to piped running water. Which low-cost innovation should the nurse teach the family to construct to ensure running water for handwashing?'', NULL, NULL, ''A stationary communal washing basin'', NULL, ''A gravity-fed \"Tippy Tap\" operated by a foot pedal'', NULL, ''A charcoal-filtered rainwater storage tank without a outlet'', NULL, ''A deep household well without a bucket system'', NULL, ''B'', 1, NULL),
(541, 130, ''mcq_single'', ''Which step of the 6-step hand hygiene technique specifically targets the web spaces and body of the thumb?'', NULL, NULL, ''Clasping the thumb and performing rotational rubbing inside the closed opposing palm'', NULL, ''Rubbing the palms together in a vertical motion'', NULL, ''Interlocking the fingers and rubbing side-to-side'', NULL, ''Massaging the wrists in a circular fashion'', NULL, ''A'', 1, NULL),
(542, 130, ''mcq_single'', ''What is the expected consequence of frequent handwashing with harsh industrial detergents or failing to dry hands completely in a clinical setting?'', NULL, NULL, ''An increased resistance of transient bacteria to standard antibiotics'', NULL, ''Skin irritation, cracking, and occupational irritant contact dermatitis'', NULL, ''Accelerated growth of fingernails leading to subungual contamination'', NULL, ''Enhanced absorption of elemental zinc through the dermal layer'', NULL, ''B'', 1, NULL),
(543, 130, ''mcq_single'', ''At which of the following household critical times must a caregiver always wash their hands with soap and water to prevent the transmission of diarrheal diseases to an under-five child?'', NULL, NULL, ''Only once at the start of the morning routine'', NULL, ''Immediately after changing a child\'s diaper or utilizing the toilet'', NULL, ''Right after watching an educational demonstration on health hygiene'', NULL, ''Just before disposing of clean, dry medical waste packages'', NULL, ''B'', 1, NULL),
(544, 130, ''mcq_single'', ''When turning off a manually operated water tap after completing a thorough handwashing procedure, what should the nurse do to prevent re-contaminating their clean hands?'', NULL, NULL, ''Turn the tap off directly using the bare, clean palm'', NULL, ''Ask the patient to reach over and close the valve'', NULL, ''Use a clean, dry paper towel or the elbow to turn off the tap'', NULL, ''Leave the water running continuously for the next person'', NULL, ''C'', 1, NULL),
(545, 130, ''mcq_single'', ''What is the ideal duration for the entire handwashing process (from wetting hands to complete drying) recommended by health organizations to ensure safety?'', NULL, NULL, ''5 to 10 seconds'', NULL, ''40 to 60 seconds'', NULL, ''5 to 10 minutes'', NULL, ''Exactly 2 minutes of continuous scrubbing'', NULL, ''B'', 1, NULL),
(546, 129, ''mcq_single'', ''Which of the following describes the most essential safety action a nurse must perform to fulfill the principle of \"Right Patient\" before administering any medication?'', NULL, NULL, ''Checking the bed number or room placard outside the patient\'s cubicle'', NULL, ''Asking a nearby roommate or family member to confirm the patient\'s identity'', NULL, ''Verifying the patient\'s identity using at least two independent identifiers, such as full name and date of birth, against the medication administration record'', NULL, ''Cross-checking the patient\'s physical appearance with a photograph on file from a previous admission'', NULL, ''C'', 1, NULL),
(547, 129, ''mcq_single'', ''A nurse is preparing an injectable medication and notes that the prescription lacks a specified route of administration. Which action best aligns with the principles of safe drug administration?'', NULL, NULL, ''Giving the medication orally since it is generally the safest alternative route'', NULL, ''Choosing the intramuscular route because it allows for rapid absorption'', NULL, ''Withholding the drug and immediately contacting the prescribing clinician to clarify the correct route'', NULL, ''Checking with a senior colleague to see how the drug is usually given on that ward'', NULL, ''C'', 1, NULL),
(548, 129, ''mcq_single'', ''Which of the following actions directly violates the principle of \"Right Documentation\" during the medication administration workflow?'', NULL, NULL, ''Recording the exact time, dose, and route immediately after the patient has swallowed the medication'', NULL, ''Documenting the administration of a medication in the electronic health record 15 minutes before actually giving it to the patient'', NULL, ''Noting a patient\'s refusal of a drug along with the clinical reason why it was not given'', NULL, ''Signing the medication administration record with a unique digital signature or initials attached to the specific time given'', NULL, ''B'', 1, NULL),
(549, 129, ''mcq_single'', ''When verifying a medication order against the stock bottle, a nurse practices the \"Right Drug\" check by reading the label at which three specific points during preparation?'', NULL, NULL, ''When arriving on shift, when setting up the medication trolley, and when finishing the round'', NULL, ''Before touching the bottle, while drawing up the liquid, and after discarding the syringe'', NULL, ''When removing the container from the storage shelf, when preparing the dose, and just before administering it to the patient'', NULL, ''At the nurse\'s station, inside the clean utility room, and during shift handover'', NULL, ''C'', 1, NULL),
(550, 129, ''mcq_single'', ''A patient refuses to take a prescribed blood pressure medication, stating that it makes them feel dizzy. Which action best reflects the nurse\'s responsibility regarding the patient\'s \"Right to Refuse\"?'', NULL, NULL, ''Hiding the medication in the patient\'s food to ensure therapeutic compliance'', NULL, ''Respecting the refusal, exploring the patient\'s concerns, assessing their vital signs, and documenting and reporting the refusal to the prescriber'', NULL, ''Insisting that the patient takes the medication anyway because it was ordered by a doctor'', NULL, ''Leaving the medication cup on the bedside table so the patient can take it later if they change their mind'', NULL, ''B'', 1, NULL),
(551, 129, ''mcq_single'', ''What is the standard recommended dose of the BCG vaccine for a newborn infant under one month of age?'', NULL, NULL, ''0.1 mL'', NULL, ''0.5 mL'', NULL, ''0.05 mL'', NULL, ''1.0 mL'', NULL, ''C'', 1, NULL),
(552, 129, ''mcq_single'', ''Which of the following routes is the only correct method for administering the BCG vaccine to a newborn?'', NULL, NULL, ''Intradermal'', NULL, ''Intramuscular'', NULL, ''Subcutaneous'', NULL, ''Oral'', NULL, ''A'', 1, NULL),
(553, 129, ''mcq_single'', ''What is the globally accepted and standard anatomical site for administering the BCG vaccine to ensure consistency in scar checking?'', NULL, NULL, ''Right anterolateral thigh'', NULL, ''Left upper arm over the deltoid muscle'', NULL, ''Left gluteal region'', NULL, ''Right upper arm over the deltoid muscle'', NULL, ''B'', 1, NULL),
(554, 129, ''mcq_single'', ''Which type of syringe and needle size should a healthcare worker select to safely administer the BCG vaccine to a newborn?'', NULL, NULL, ''A 2 mL syringe with a 21G long needle'', NULL, ''A 0.5 mL auto-disable syringe with a 23G needle'', NULL, ''A 1 mL insulin syringe with a pre-fixed 30G needle'', NULL, ''A 1 mL tuberculin syringe with a 26G or 27G short-bevel needle'', NULL, ''D'', 1, NULL),
(555, 129, ''mcq_single'', ''At what angle should the needle be inserted into the newborn\'s skin to achieve a proper intradermal injection of the BCG vaccine?'', NULL, NULL, ''45 degrees'', NULL, ''10 to 15 degrees'', NULL, ''90 degrees'', NULL, ''30 degrees'', NULL, ''B'', 1, NULL);
INSERT INTO `objective_questions` (`id`, `exam_id`, `question_type`, `question_text`, `question_image`, `question_data`, `option_a`, `option_a_image`, `option_b`, `option_b_image`, `option_c`, `option_c_image`, `option_d`, `option_d_image`, `correct_option`, `mark`, `deleted_at`) VALUES
(556, 129, ''mcq_single'', ''Which clinical sign immediately indicates that the BCG vaccine has been correctly administered into the intradermal layer?'', NULL, NULL, ''A rapid flash of blood back into the syringe hub'', NULL, ''Immediate blanching of the entire upper arm circumference'', NULL, ''The formation of a raised, blanched wheal measuring about 5 to 7 mm'', NULL, ''Deep bruising and induration around the puncture site'', NULL, ''C'', 1, NULL),
(557, 129, ''mcq_single'', ''Which fluid must be used as the appropriate diluent to reconstitute freeze-dried BCG vaccine?'', NULL, NULL, ''Sterile Normal Saline (0.9% Sodium Chloride)'', NULL, ''Sterile Water for Injection'', NULL, ''5% Dextrose Solution'', NULL, ''Phosphate Buffered Saline'', NULL, ''A'', 1, NULL),
(558, 129, ''mcq_single'', ''Once a vial of live-attenuated BCG vaccine is reconstituted, what is the maximum time it can be kept in the cold chain before it must be discarded?'', NULL, NULL, ''24 hours'', NULL, ''12 hours'', NULL, ''1 hour'', NULL, ''6 hours'', NULL, ''D'', 1, NULL),
(559, 129, ''mcq_single'', ''When maintaining infection prevention protocols before a BCG injection, why should alcohol-based swabs be avoided, or if used, allowed to dry completely before needle insertion?'', NULL, NULL, ''Residual alcohol can inactivate the live bacteria in the vaccine'', NULL, ''Alcohol alters the osmolarity of the saline diluent'', NULL, ''Alcohol prevents the formation of the intradermal wheal'', NULL, ''Residual alcohol causes severe permanent skin hyperpigmentation'', NULL, ''A'', 1, NULL),
(560, 129, ''mcq_single'', ''What is the expected normal course of a local reaction at the injection site following a correct BCG vaccination in a newborn?'', NULL, NULL, ''A systemic rash appearing within 24 hours and lasting two weeks'', NULL, ''A small papule appearing after 2-3 weeks, turning into a minor ulcer, and leaving a small permanent scar by 6-12 weeks'', NULL, ''An immediate large purulent abscess that heals within 48 hours without scarring'', NULL, ''No local changes or visible marks on the skin at any stage'', NULL, ''B'', 1, NULL),
(561, 129, ''mcq_single'', ''What advice should a nurse give to a mother regarding the proper home care of a normal post-BCG vaccination ulcer or nodule on her baby\'s arm?'', NULL, NULL, ''Keep the area clean and dry, and do not apply any ointments, traditional medicines, or bandages'', NULL, ''Squeeze the nodule regularly to express any fluid or pus'', NULL, ''Apply a thick layer of topical antibiotic ointment and cover it tightly with an airtight dressing'', NULL, ''Rub the site vigorously with alcohol wipes twice daily'', NULL, ''A'', 1, NULL),
(562, 129, ''mcq_single'', ''Which of the following is a absolute contraindication for administering the live-attenuated BCG vaccine to a newborn infant?'', NULL, NULL, ''Prematurity with a birth weight of 2.2 kg'', NULL, ''Known or highly suspected symptomatic HIV infection or severe immunodeficiency'', NULL, ''Mild physiological neonatal jaundice'', NULL, ''Mother having a history of a resolved urinary tract infection during pregnancy'', NULL, ''B'', 1, NULL),
(563, 129, ''mcq_single'', ''What is the most likely local complication if a healthcare provider accidentally administers the BCG vaccine too deeply into the subcutaneous tissue instead of the intradermal layer?'', NULL, NULL, ''Rapid systemic anaphylactic shock'', NULL, ''Total failure of the child to develop any immune response'', NULL, ''Local subcutaneous abscess formation and suppurative lymphadenitis'', NULL, ''Transient paralysis of the left radial nerve'', NULL, ''C'', 1, NULL),
(564, 129, ''mcq_single'', ''During the reconstitution of the BCG vaccine, which infection control practice is vital to protect the potency of this highly light-sensitive vaccine?'', NULL, NULL, ''Keeping the vial exposed to direct sunlight to warm it to body temperature'', NULL, ''Reconstituting the vaccine in a dark room under ultraviolet light'', NULL, ''Protecting the vial from direct sunlight and artificial ultraviolet light by keeping it shaded or wrapped'', NULL, ''Heating the diluent vial in a water bath before mixing'', NULL, ''C'', 1, NULL),
(565, 129, ''mcq_single'', ''According to standard infection prevention guidelines, what should the vaccinator do immediately after withdrawing the needle from the newborn\'s arm following a BCG injection?'', NULL, NULL, ''Recap the needle using both hands before disposal'', NULL, ''Drop the uncovered syringe and needle directly into a puncture-proof sharps safety box'', NULL, ''Clean the needle with an antiseptic wipe before placing it in a plastic trash bag'', NULL, ''Cut the needle off with scissors and throw the syringe body in the general waste bin'', NULL, ''B'', 1, NULL),
