(644, 135, ''mcq_single'', ''Which stain is most commonly used for peripheral blood smears?'', NULL, NULL, ''Gram stain'', NULL, ''Wright-Giemsa stain'', NULL, ''Acid-fast stain'', NULL, ''India ink'', NULL, ''B'', 1, NULL),
(645, 135, ''mcq_single'', ''In a normal cerebrospinal fluid (CSF) sample, which type of cell is predominantly found?'', NULL, NULL, ''Neutrophil'', NULL, ''Eosinophil'', NULL, ''Lymphocyte'', NULL, ''Macrophage'', NULL, ''C'', 1, NULL),
