(681, 134, ''mtf'', ''Concerning the hormone Insulin:'', NULL, ''{\"statements\":[{\"text\":\"It is produced by the beta cells of the pancreas.\"},{\"text\":\"It increases blood glucose levels.\"},{\"text\":\"It promotes glycogen synthesis in the liver.\"},{\"text\":\"It is primarily produced by the adrenal glands.\"}]}'', '''', NULL, '''', NULL, '''', NULL, '''', NULL, ''TFTF'', 4, NULL),
(682, 134, ''mtf'', ''Concerning routine urinalysis:'', NULL, ''{\"statements\":[{\"text\":\"Specific gravity measures the concentrating ability of the kidneys.\"},{\"text\":\"A positive nitrite test strongly suggests a viral infection.\"},{\"text\":\"The presence of glucose always indicates diabetes mellitus.\"},{\"text\":\"Leukocyte esterase indicates the presence of white blood cells.\"}]}'', '''', NULL, '''', NULL, '''', NULL, '''', NULL, ''TFFT'', 4, NULL),
(683, 134, ''mtf'', ''Concerning the ABO blood group system:'', NULL, ''{\"statements\":[{\"text\":\"A person with group AB blood has anti-A and anti-B antibodies in their plasma.\"},{\"text\":\"The O gene is amorphic (recessive).\"},{\"text\":\"Group O individuals lack A and B antigens on their red cells.\"},{\"text\":\"Group A individuals can safely receive group B red blood cells.\"}]}'', '''', NULL, '''', NULL, '''', NULL, '''', NULL, ''FTTF'', 4, NULL),
(684, 134, ''mtf'', ''Concerning lipid profiling:'', NULL, ''{\"statements\":[{\"text\":\"Triglycerides are the main storage form of lipids.\"},{\"text\":\"Chylomicrons are responsible for transporting exogenous dietary lipids.\"},{\"text\":\"LDL transports cholesterol from the tissues back to the liver.\"},{\"text\":\"Fasting for 10-12 hours is recommended before a lipid panel.\"}]}'', '''', NULL, '''', NULL, '''', NULL, '''', NULL, ''TTFT'', 4, NULL),
(685, 134, ''mtf'', ''Concerning hematopoiesis:'', NULL, ''{\"statements\":[{\"text\":\"Extramedullary hematopoiesis occurs in the liver and spleen.\"},{\"text\":\"The bone marrow is the primary site of hematopoiesis in adults.\"},{\"text\":\"Megakaryocytes give rise to red blood cells.\"},{\"text\":\"Erythropoietin is mainly produced by the liver.\"}]}'', '''', NULL, '''', NULL, '''', NULL, '''', NULL, ''TTFF'', 4, NULL),
(686, 134, ''mtf'', ''Concerning laboratory safety:'', NULL, ''{\"statements\":[{\"text\":\"Mouth pipetting is acceptable if working with non-infectious solutions.\"},{\"text\":\"Needles should never be recapped before disposal.\"},{\"text\":\"A Class II Biological Safety Cabinet protects both the user and the sample.\"},{\"text\":\"Standard precautions assume all patient samples are infectious.\"}]}'', '''', NULL, '''', NULL, '''', NULL, '''', NULL, ''FTTT'', 4, NULL),
(687, 134, ''mtf'', ''Concerning clinical enzymology:'', NULL, ''{\"statements\":[{\"text\":\"Enzymes act as biological catalysts.\"},{\"text\":\"Enzyme activity is unaffected by temperature changes.\"},{\"text\":\"Creatine kinase (CK) is elevated in muscle disorders.\"},{\"text\":\"Lactate dehydrogenase (LDH) is highly specific to the liver.\"}]}'', '''', NULL, '''', NULL, '''', NULL, '''', NULL, ''TFTF'', 4, NULL),
(688, 134, ''mtf'', ''Concerning the immune system:'', NULL, ''{\"statements\":[{\"text\":\"T cells mature in the thymus.\"},{\"text\":\"B cells are responsible for cell-mediated immunity.\"},{\"text\":\"Macrophages are phagocytic cells.\"},{\"text\":\"Complement proteins are part of the innate immune system.\"}]}'', '''', NULL, '''', NULL, '''', NULL, '''', NULL, ''TFTT'', 4, NULL),
(689, 134, ''mtf'', ''Concerning the thyroid gland and its function:'', NULL, ''{\"statements\":[{\"text\":\"Thyroid-stimulating hormone (TSH) is produced by the thyroid gland.\"},{\"text\":\"T4 is the major circulating thyroid hormone.\"},{\"text\":\"Iodine is essential for the synthesis of thyroid hormones.\"},{\"text\":\"Hypothyroidism typically presents with a decreased TSH level.\"}]}'', '''', NULL, '''', NULL, '''', NULL, '''', NULL, ''FTTF'', 4, NULL),
(690, 134, ''mtf'', ''Concerning Mycobacterium tuberculosis:'', NULL, ''{\"statements\":[{\"text\":\"It is an obligate anaerobe.\"},{\"text\":\"It retains the carbolfuchsin stain after acid-alcohol decolorization.\"},{\"text\":\"It is rapidly growing and visible on solid media within 24 hours.\"},{\"text\":\"Lowenstein-Jensen is a traditional medium used for its cultivation.\"}]}'', '''', NULL, '''', NULL, '''', NULL, '''', NULL, ''FTFT'', 4, NULL),
