(731, 134, ''mtf'', ''Concerning autoimmune diseases and their characteristic antibodies:'', NULL, ''{\"statements\":[{\"text\":\"Systemic Lupus Erythematosus (SLE) is associated with anti-dsDNA.\"},{\"text\":\"Hashimoto\'s thyroiditis is characterized by anti-TPO (thyroid peroxidase) antibodies.\"},{\"text\":\"Graves\' disease is caused by antibodies that destroy TSH receptors.\"},{\"text\":\"Primary Biliary Cholangitis is strongly associated with Anti-Mitochondrial Antibodies (AMA).\"}]}'', '''', NULL, '''', NULL, '''', NULL, '''', NULL, ''TTFT'', 4, NULL),
(732, 134, ''mtf'', ''Concerning microscopic urinalysis crystals and their typical pH:'', NULL, ''{\"statements\":[{\"text\":\"Uric acid crystals are typically found in acidic urine.\"},{\"text\":\"Triple phosphate crystals are typically found in alkaline urine.\"},{\"text\":\"Calcium oxalate crystals can only form in alkaline urine.\"},{\"text\":\"Cystine crystals are considered a normal finding in healthy individuals.\"}]}'', '''', NULL, '''', NULL, '''', NULL, '''', NULL, ''TTFF'', 4, NULL),
(733, 134, ''mtf'', ''Concerning the diagnosis of Syphilis:'', NULL, ''{\"statements\":[{\"text\":\"Treponema pallidum can be easily cultured on routine blood agar.\"},{\"text\":\"RPR and VDRL are considered non-treponemal screening tests.\"},{\"text\":\"A positive RPR must be confirmed with a treponemal test like TP-PA or FTA-ABS.\"},{\"text\":\"Biological false positives do not occur with non-treponemal tests.\"}]}'', '''', NULL, '''', NULL, '''', NULL, '''', NULL, ''FTTF'', 4, NULL),
(734, 134, ''mtf'', ''Concerning quality assurance and method evaluation:'', NULL, ''{\"statements\":[{\"text\":\"Precision refers to the reproducibility of a test result.\"},{\"text\":\"Accuracy refers to how close a test result is to the true value.\"},{\"text\":\"A test can be highly precise but highly inaccurate.\"},{\"text\":\"Systemic error primarily affects a test\'s precision rather than its accuracy.\"}]}'', '''', NULL, '''', NULL, '''', NULL, '''', NULL, ''TTTF'', 4, NULL),
(735, 134, ''mtf'', ''Concerning viral markers in Hepatitis B infection:'', NULL, ''{\"statements\":[{\"text\":\"HBsAg is the first serological marker to appear in acute infection.\"},{\"text\":\"Anti-HBs indicates immunity due to past infection or vaccination.\"},{\"text\":\"HBeAg positivity generally indicates high viral infectivity.\"},{\"text\":\"Anti-HBc IgM is typically elevated in chronic, long-term infections.\"}]}'', '''', NULL, '''', NULL, '''', NULL, '''', NULL, ''TTTF'', 4, NULL),
