(1030, 138, ''mtf'', ''The Periodic acid-Schiff (PAS) stain gives a bright magenta color and is useful for identifying:'', NULL, ''{\"statements\":[{\"text\":\"Connective tissue fibers\"},{\"text\":\"Fungal elements\"},{\"text\":\"Glycogen and basement membranes\"},{\"text\":\"Nuclei\"},{\"text\":\"Elastic fibre\"}]}'', '''', NULL, '''', NULL, '''', NULL, '''', NULL, ''FFTFF'', 5, NULL),
(1031, 138, ''mtf'', ''The best statement related to the autolysis.'', NULL, ''{\"statements\":[{\"text\":\"Autolysis is decay of tissues caused mainly by bacteria\"},{\"text\":\"Autolysis is decay of tissues caused mainly by action of the immune system\"},{\"text\":\"Autolysis is decay of tissues caused mainly by enzymes produced inside the tissue\"},{\"text\":\"Autolysis is decay of tissues caused by chemical compounds into which is the sample placed after harvesting.\"},{\"text\":\"Autolysis is decay of tissues caused by lysis\"}]}'', '''', NULL, '''', NULL, '''', NULL, '''', NULL, ''FFTFF'', 5, NULL),
(1032, 138, ''mtf'', ''Degradation of a biological material caused by bacteria is called:'', NULL, ''{\"statements\":[{\"text\":\"Apoptosis\"},{\"text\":\"Autolysis\"},{\"text\":\"Liquefaction\"},{\"text\":\"Putrefaction\"},{\"text\":\"Institutionalization\"}]}'', '''', NULL, '''', NULL, '''', NULL, '''', NULL, ''FFFTF'', 5, NULL),
(1033, 138, ''mtf'', ''Among following dyes, only one is not acidic.'', NULL, ''{\"statements\":[{\"text\":\"Eosin\"},{\"text\":\"Orange G\"},{\"text\":\"Anilin blue\"},{\"text\":\"Haematoxylin\"},{\"text\":\"Picric acid\"}]}'', '''', NULL, '''', NULL, '''', NULL, '''', NULL, ''TTTFT'', 5, NULL),
(1034, 138, ''mtf'', ''The dyes that is not basic:'', NULL, ''{\"statements\":[{\"text\":\"Hematein\"},{\"text\":\"Orange G\"},{\"text\":\"Hematoxylin\"},{\"text\":\"Methylen blue\"},{\"text\":\"Green\"}]}'', '''', NULL, '''', NULL, '''', NULL, '''', NULL, ''TFTTF'', 5, NULL),
(1035, 138, ''mtf'', ''Technique to detect specific sequence of nucleic acid on the tissue section:'', NULL, ''{\"statements\":[{\"text\":\"In situ hybridization\"},{\"text\":\"Lectin histochemistry\"},{\"text\":\"Immunohistochemistry\"},{\"text\":\"Feulgen\'s method\"},{\"text\":\"Saponification\"}]}'', '''', NULL, '''', NULL, '''', NULL, '''', NULL, ''FFFTF'', 5, NULL),
(1036, 138, ''mtf'', ''The cellular structure that is stained by aldehyde fuchsin:'', NULL, ''{\"statements\":[{\"text\":\"Reticular fibers\"},{\"text\":\"Polysaccharides\"},{\"text\":\"Elastic fibers\"},{\"text\":\"Mucus\"},{\"text\":\"Nucleus\"}]}'', '''', NULL, '''', NULL, '''', NULL, '''', NULL, ''FFTFF'', 5, NULL);
