(1282, 100, ''Inflate the retention balloon with the pre-filled syringe of sterile water.'', ''0,0.5,1'', NULL),
(1283, 100, ''Pull back gently until resistance is felt to anchor the balloon.'', ''0,0.5,1'', NULL),
(1284, 100, ''Attach the drainage bag below bladder level to the immovable bed frame.'', ''0,0.5,1'', NULL),
