(1392, 116, ''Washes and dries hand (1/2)'', ''0,0.25,0.5'', NULL),
(1393, 116, ''Dons gloves(1/4)'', ''0,0.125,0.25'', NULL),
(1394, 116, ''Adjusts the head of the bed to a flat position(1/4)'', ''0,0.125,0.25'', NULL),
(1395, 116, ''Locks the wheels on the bed (1/4)'', ''0,0.125,0.25'', NULL),
(1396, 116, ''Moves the client closer to the right side of the bed(1/2)'', ''0,0.25,0.5'', NULL),
(1397, 116, ''Stands on the side of the bed nearest to the client, places the clients near arm across the chest, abducts the far shoulder from the side of the body and externally rotates (1)'', ''0,0.5,1'', NULL),
(1398, 116, ''Places the client\'s near ankle and foot across the far ankle and foot(1/2)'', ''0,0.25,0.5'', NULL),
(1399, 116, ''Places one hand on the client\'s far hip and the other on the far shoulder, instructs the asssistant to do same, and together roll the client to the right lateral position (1/2)'', ''0,0.25,0.5'', NULL),
(1400, 116, ''Places pillows to support the head, neck and upper segment of the arm (1/2)'', ''0,0.25,0.5'', NULL),
(1401, 116, ''Ensures top hip and knee are flexed (1/2)'', ''0,0.25,0.5'', NULL),
(1402, 116, ''Ensures upper arm and shoulder are rotated internally and adducted with a pillow under the upper segment of the arm (3/4)'', ''0,0.375,0.75'', NULL),
(1403, 116, ''Ensures upper thigh and leg are rotated are rotated internally and adducted with pillow under the leg and thigh (1/2)'', ''0,0.25,0.5'', NULL),
(1404, 116, ''Tidies the work area (1/4)'', ''0,0.125,0.25'', NULL),
