(1410, 117, ''Dons gloves(1/4)'', ''0,0.125,0.25'', NULL),
(1411, 117, ''Assists client to sit up or to lie with the head tilted towards the side of the left ear(3/4)'', ''0,0.375,0.75'', NULL),
