(1472, 126, ''Preparation: Rolls up sleeves, removes all wrist jewelry/rings, and verbalizes checking skin for cuts.'', ''0,0.5,1'', NULL),
(1473, 126, ''Initial Wetting: Turns on the tap/water flow, thoroughly wets hands with running water, and applies enough soap to cover all surfaces.'', ''0,0.5,1'', NULL),
(1474, 126, ''Step 1: Palms: Rubs hands palm to palm in a vigorous circular motion.'', ''0,1,2'', NULL),
(1475, 126, ''Step 2: Back of Hands: Rubs the right palm over the left dorsum (back of hand) with interlaced fingers, and vice versa.'', ''0,1,2'', NULL),
(1476, 126, ''Step 3: Interlaced Palms: Rubs palm to palm with fingers interlaced to clean between the fingers.'', ''0,1,2'', NULL),
(1477, 126, ''Step 4: Back of Fingers :Interlocks the fingers (backs of fingers to opposing palms) and rubs them side-to-side.'', ''0,1,2'', NULL),
(1478, 126, ''Step 5: Thumbs: Rotational rubbing of the left thumb clasped in the right palm, and vice versa.'', ''0,1,2'', NULL),
(1479, 126, ''Step 6: Fingernails/Tips: Rubs the fingertips of the right hand rotationally backward and forward in the left palm, and vice versa.'', ''0,1,2'', NULL),
(1480, 126, ''Rinsing & Drying: Rinses hands thoroughly under running water without rubbing clean hands back against the unwashed tap. Air-dries completely or uses a clean, single-use towel.'', ''0,1,2'', NULL),
(1481, 126, ''Timing & Teaching:  Ensures the scrubbing phase lasts for at least 20 seconds and effectively guides the actor to mirror the steps.'', ''0,0.5,1'', NULL);
